В `src/main.rs` мы можем написать следующий код:

```rust
use std::env;
use std::fs;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len()!= 3 {
        println!("Usage: {} <string> <substring>", args[0]);
        return;
    }

    let string = &args[1];
    let substring = &args[2];

    let result = search_substring(string, substring);
    println!("{}", result);
}

fn search_substring(string: &str, substring: &str) -> String {
    let mut result = String::new();
    for (i, c) in string.chars().enumerate() {
        if c == substring.chars().next().unwrap() {
            let mut match_found = true;
            for (j, c2) in string.chars().enumerate().skip(i) {
                if c2!= substring.chars().nth(j - i).unwrap() {
                    match_found = false;
                    break;
                }
            }
            if match_found {
                result.push_str(&format!("{}: {}", i, substring));
            }
        }
    }
    result
}
```

